corrected_code:
const orderSubscriptionResolvers = {
  Subscription: {
    orderStatusUpdated: {
      subscribe: withFilter(
        () => pubsub.asyncIterator(['ORDER_STATUS_CHANGED']),
        async (payload, variables, context) => {
          if (!context.user) return false;
          const order = await Order.findByPk(variables.orderId);
          return order && order.userId === context.user.id && payload.orderId === variables.orderId;
        }
      ),
      resolve: (payload) => payload.statusUpdate
    }
  }
};
